# Additional numerical topics, each checked by its defining formula or simulation.
for frames,seq in [(3,[1,2,3,1,4,2,5,1]),(3,[2,1,2,3,4,1,2,5]),(4,[1,2,3,4,1,5,2,6]),(2,[1,2,1,3,2,4,1]),(3,[4,3,2,4,1,2,5,3])]:
 for method in ['FIFO','LRU']:
  mem=[];faults=0;steps=[]
  for x in seq:
   hit=x in mem
   if not hit:
    faults+=1
    if len(mem)==frames:mem.pop(0)
    mem.append(x)
   elif method=='LRU':mem.remove(x);mem.append(x)
   steps.append(f'{x}: {"적중" if hit else "부재"}')
  term('계산',f'빈 페이지 프레임 {frames}개에서 {method} 페이지 교체를 사용한다. 참조열 {", ".join(map(str,seq))}의 페이지 부재 횟수는?',str(faults),' / '.join(steps)+f'. 총 {faults}회입니다.',7,sid=3)
